def make_doc():
    d = BaseDocTemplate(
        str(OUT), pagesize=FMT["page_size"],
        leftMargin=FMT["margin_left_cm"] * cm,
        rightMargin=FMT["margin_right_cm"] * cm,
        topMargin=FMT["margin_top_cm"] * cm,
        bottomMargin=FMT["margin_bottom_cm"] * cm,
        title="ChurnIQ — Customer Churn Prediction & Business Intelligence System",
        author="[STUDENT NAME]", subject="Project Report",
    )
    fr = Frame(d.leftMargin, d.bottomMargin, d.width, d.height, id="n")
    d.addPageTemplates([
        PageTemplate(id="First", frames=[fr], onPage=first_page),
        PageTemplate(id="Later", frames=[fr], onPage=later_pages),
    ])
    return d


# ------------------------------------------------------------------
# Iterative build.
#
# The table of contents and the two lists carry real page numbers, and
# those lists change length as they are filled in, which shifts every
# page after them. The document is therefore rebuilt until the page
# assignments and the length of the front matter stop changing.
# ------------------------------------------------------------------
MAX_PASSES = 8
previous = None

for attempt in range(1, MAX_PASSES + 1):
    story.clear()
    figno.clear()
    tabno.clear()
    RAW_PAGE_OF.clear()
    if attempt > 1:
        PASS = 2                      # registries are already populated
    build_story()
    make_doc().build(story)

    if "ch:1" in RAW_PAGE_OF:
        FRONT_MATTER_PAGES = RAW_PAGE_OF["ch:1"] - 1

    # Translate physical pages into the labels the next pass will print.
    PAGE_OF.clear()
    for key, raw in RAW_PAGE_OF.items():
        PAGE_OF[key] = _printed_label(raw)

    current = (FRONT_MATTER_PAGES, dict(PAGE_OF))
    if current == previous:
        break
    previous = current
else:
    print("Warning: page numbering did not settle after "
          f"{MAX_PASSES} passes.")

print(f"Converged after {attempt} pass(es); "
      f"front matter = {FRONT_MATTER_PAGES} pages.")
print(f"Report written to {OUT}")
